#!/usr/bin/env node
/**
 * Build the Electron installer with code signing.
 *
 * Loads CSC_LINK and CSC_KEY_PASSWORD from build/private/codesign.env
 * (gitignored), then runs electron-builder. The env file is generated by
 * scripts/generate-codesign-cert.ps1.
 *
 * Safety gates (applied in order):
 *   1. Fail fast if signing env/thumbprint pin is missing, unless ADSI_ALLOW_UNSIGNED=1.
 *      Unsigned installers cannot auto-update existing signed installs
 *      because electron-updater rejects publisher-hash mismatches.
 *   2. Reject dirty/behind/already-tagged signed-release inputs.
 *   3. Non-mutatingly verify committed full-guide PDF provenance.
 *   4. Regenerate/verify Forecast build identity and rebuild the one-file EXE.
 *   5. Post-build signature verification via Get-AuthenticodeSignature.
 *      Confirms the file was actually signed (electron-builder can silently
 *      skip signing on timestamp-server errors) and pins the thumbprint to
 *      build/private/codesign-thumbprint.txt so a stray cert can't ship.
 *   6. Installer size floor + SHA-512 log. Rejects builds that are
 *      implausibly small (missing Python services, broken extraResources)
 *      and logs the SHA-512 that electron-updater will expect in latest.yml.
 *
 * Usage:
 *   node scripts/build-installer-signed.js
 *   npm run build:installer:signed
 *
 * Dev escape hatch:
 *   ADSI_ALLOW_UNSIGNED=1 node scripts/build-installer-signed.js
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { spawnSync } = require('child_process');
const { parsePinnedThumbprint } = require('./release-build-guards');

const repoRoot = path.resolve(__dirname, '..');
const envFile = path.join(repoRoot, 'build', 'private', 'codesign.env');
const thumbFile = path.join(repoRoot, 'build', 'private', 'codesign-thumbprint.txt');
const verifyScript = path.join(repoRoot, 'scripts', 'verify-signed-installer.ps1');
const releaseDir = path.join(repoRoot, 'release');
const pythonCommand = process.env.PYTHON || 'python';

const ALLOW_UNSIGNED = process.env.ADSI_ALLOW_UNSIGNED === '1';
// 150 MB floor — post-v2.8.13 slimmed builds land around 180-220 MB after
// removing duplicate ffmpeg/go2rtc/service-dist payloads from the asar and
// pinning locales to en-US (see package.json files globs). This includes three
// Python service EXEs (InverterCoreService, ForecastCoreService, CalibratorService).
// A broken build missing any Python service EXE would still be well under 100 MB.
// Historical pre-slim builds were ~500-620 MB.
const MIN_INSTALLER_BYTES = 150 * 1024 * 1024;

const env = { ...process.env };
let signed = false;
let expectedThumbprint = null;

if (fs.existsSync(envFile)) {
  const content = fs.readFileSync(envFile, 'utf8');
  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq < 0) continue;
    const key = line.slice(0, eq).trim();
    const value = line.slice(eq + 1).trim();
    if (key) env[key] = value;
  }

  // CSC_LINK in the env file is repo-relative; resolve to absolute path so
  // electron-builder finds it regardless of cwd.
  if (env.CSC_LINK && !path.isAbsolute(env.CSC_LINK)) {
    env.CSC_LINK = path.resolve(repoRoot, env.CSC_LINK);
  }

  if (env.CSC_LINK && env.CSC_KEY_PASSWORD && fs.existsSync(env.CSC_LINK)) {
    signed = true;
    console.log('[build-installer-signed] Code signing enabled');
    console.log('[build-installer-signed]   PFX:', env.CSC_LINK);
  } else {
    console.warn('[build-installer-signed] Env file present but PFX missing or invalid:');
    console.warn('  CSC_LINK         =', env.CSC_LINK || '(unset)');
    console.warn('  CSC_KEY_PASSWORD =', env.CSC_KEY_PASSWORD ? '(set)' : '(unset)');
  }
} else {
  console.warn('[build-installer-signed] Code signing env file missing:', envFile);
  console.warn('[build-installer-signed] Run: powershell -ExecutionPolicy Bypass -File scripts/generate-codesign-cert.ps1');
}

// ─── GATE 1: Require signing unless explicitly opted out ────────────────────
if (!signed) {
  if (!ALLOW_UNSIGNED) {
    console.error('');
    console.error('[build-installer-signed] FATAL: code signing is required for release builds.');
    console.error('  Either:');
    console.error('    (a) provision build/private/codesign.env with a valid PFX + password, or');
    console.error('    (b) set ADSI_ALLOW_UNSIGNED=1 to build an unsigned installer for dev/testing.');
    console.error('');
    console.error('  Unsigned installers CANNOT auto-update existing signed installations');
    console.error('  because electron-updater rejects publisher-hash mismatches.');
    process.exit(1);
  }
  console.warn('[build-installer-signed] ADSI_ALLOW_UNSIGNED=1 — proceeding with UNSIGNED build');
  delete env.CSC_LINK;
  delete env.CSC_KEY_PASSWORD;
}

if (signed) {
  if (!fs.existsSync(thumbFile)) {
    console.error('[build-installer-signed] FATAL: required thumbprint pin file is missing:', thumbFile);
    process.exit(1);
  }
  try {
    expectedThumbprint = parsePinnedThumbprint(fs.readFileSync(thumbFile, 'utf8'));
  } catch (error) {
    console.error('[build-installer-signed] FATAL: invalid thumbprint pin:', error.message);
    process.exit(1);
  }
}

// GATE 1.25: rebuild ForecastCoreService with current build identity.
//
// forecast_engine.py is frozen into a one-file executable. Reusing an older
// dist/ForecastCoreService.exe would make the installer pass while shipping
// stale code, so every installer build regenerates/verifies its identity and
// rebuilds the executable. Signed release builds additionally require a clean,
// complete, promotion-eligible identity. ADSI_ALLOW_UNSIGNED=1 remains a safe
// development escape hatch: the build proceeds, but its bundled identity is
// explicitly promotion_eligible=false.
function runForecastBuildStep(label, args, stepEnv = env) {
  console.log('[build-installer-signed] ' + label + ': ' + pythonCommand + ' ' + args.join(' '));
  const result = spawnSync(pythonCommand, args, {
    cwd: repoRoot,
    stdio: 'inherit',
    env: stepEnv,
    shell: false,
  });
  if (result.error) {
    console.error('[build-installer-signed] FATAL: ' + label + ' could not start:', result.error.message);
    process.exit(1);
  }
  if (result.status !== 0) {
    console.error('[build-installer-signed] FATAL: ' + label + ' failed with status', result.status);
    process.exit(result.status || 1);
  }
}

const forecastBuildChannel = signed ? 'signed-release' : 'development';
const identityArgs = [
  'scripts/generate_build_info.py',
  '--build-channel', forecastBuildChannel,
];
if (signed) identityArgs.push('--require-promotion-eligible', '--require-release-ready');
runForecastBuildStep('Generating Forecast build identity', identityArgs);

if (signed) {
  console.log('[build-installer-signed] Verifying committed user-guide PDF provenance: npm run docs:pdf -- --check');
  const docsResult = spawnSync('npm', ['run', 'docs:pdf', '--', '--check'], {
    cwd: repoRoot,
    stdio: 'inherit',
    env,
    shell: process.platform === 'win32',
  });
  if (docsResult.error || docsResult.status !== 0) {
    console.error(
      '[build-installer-signed] FATAL: complete user-guide PDF preflight failed.',
      docsResult.error ? docsResult.error.message : 'status=' + docsResult.status,
    );
    process.exit(docsResult.status || 1);
  }
} else {
  console.log('[build-installer-signed] Skipping release PDF preflight for unsigned development build.');
}

const forecastBuildEnv = {
  ...env,
  ADSI_REQUIRE_PROMOTION_ELIGIBLE: signed ? '1' : '0',
  ADSI_FORECAST_BUILD_CHANNEL: forecastBuildChannel,
};
runForecastBuildStep(
  'Rebuilding ForecastCoreService',
  ['-m', 'PyInstaller', '--noconfirm', 'services/ForecastCoreService.spec'],
  forecastBuildEnv,
);

const identityCheckArgs = [
  'scripts/generate_build_info.py',
  '--check',
  '--build-channel', forecastBuildChannel,
];
if (signed) identityCheckArgs.push('--require-promotion-eligible', '--require-release-ready');
runForecastBuildStep('Verifying Forecast build identity', identityCheckArgs);

const forecastExe = path.join(repoRoot, 'dist', 'ForecastCoreService.exe');
const forecastSource = path.join(repoRoot, 'services', 'forecast_engine.py');
const forecastBuildInfo = path.join(repoRoot, 'services', 'forecast-build-info.json');
if (!fs.existsSync(forecastExe)) {
  console.error('[build-installer-signed] FATAL: Forecast build completed without:', forecastExe);
  process.exit(1);
}
const forecastExeMtime = fs.statSync(forecastExe).mtimeMs;
const newestForecastInput = Math.max(
  fs.statSync(forecastSource).mtimeMs,
  fs.statSync(forecastBuildInfo).mtimeMs,
);
if (forecastExeMtime < newestForecastInput) {
  console.error('[build-installer-signed] FATAL: ForecastCoreService.exe is older than its source/build identity.');
  process.exit(1);
}
console.log('[build-installer-signed] ForecastCoreService rebuilt with verified current identity.');

// ─── GATE 1.5: free a locked stale build dir ────────────────────────────────
//
// Symptom this prevents: electron-builder dies mid-pack with
//   "The process cannot access the file 'app.asar' because it is being
//    used by another process"
// on release/win-unpacked/resources/app.asar.
//
// Root causes seen in practice (all leftovers from a PRIOR build/smoke
// cycle on the same box):
//   • a hung `app-builder.exe` / `electron.exe` from an interrupted build,
//   • a packaged "ADSI Inverter Dashboard.exe" launched by an e2e/Electron
//     smoke that never exited — it keeps app.asar mapped,
//   • a transient Defender/Windows-Search on-access scan handle that a
//     tight delete-retry loop kept re-triggering.
//
// We proactively (a) kill ONLY repo-owned stale build/app processes whose
// image lives under the output dir (never system services), then (b) remove
// win-unpacked with bounded retry/backoff (rmSync handles the short-lived
// AV/Search handle), then (c) fail fast with a precise, actionable message
// if it is still wedged — so the failure is legible instead of a confusing
// mid-pack electron-builder crash.
function freeStaleBuildDir() {
  let outDir = 'release';
  try {
    const pkg = require(path.join(repoRoot, 'package.json'));
    outDir = (pkg.build && pkg.build.directories && pkg.build.directories.output) || 'release';
  } catch (_) {}
  const outAbs = path.join(repoRoot, outDir);
  const winUnpacked = path.join(outAbs, 'win-unpacked');
  if (!fs.existsSync(winUnpacked)) return;

  if (process.platform === 'win32') {
    // Kill stale processes whose executable path is under the output dir.
    // Scoped to outAbs so we never touch the running dashboard, MsMpEng,
    // SearchIndexer, or anything outside this repo's build tree.
    const ps =
      `Get-CimInstance Win32_Process | ` +
      `Where-Object { $_.ExecutablePath -and $_.ExecutablePath -like '${outAbs.replace(/'/g, "''")}\\*' } | ` +
      `ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue; $_.ProcessId }`;
    try {
      const r = spawnSync('powershell',
        ['-NoProfile', '-NonInteractive', '-Command', ps],
        { encoding: 'utf8', timeout: 30000 });
      const killed = String(r.stdout || '').trim();
      if (killed) {
        console.log('[build-installer-signed] Terminated stale build/app process(es) holding',
          outDir + '\\win-unpacked:', killed.split(/\s+/).join(', '));
      }
    } catch (_) { /* best-effort — the rmSync retry below is the real guard */ }
  }

  // rmSync has built-in EBUSY/EPERM/ENOTEMPTY backoff (maxRetries/retryDelay),
  // which is exactly the right tool for a sub-second AV/indexer handle.
  try {
    fs.rmSync(winUnpacked, { recursive: true, force: true, maxRetries: 8, retryDelay: 750 });
  } catch (err) {
    if (fs.existsSync(winUnpacked)) {
      console.error('');
      console.error('[build-installer-signed] FATAL: cannot clear a stale build dir.');
      console.error('  Locked path : ' + path.join(winUnpacked, 'resources', 'app.asar'));
      console.error('  Reason      : ' + (err && err.message ? err.message : 'in use by another process'));
      console.error('  No repo-owned process holds it, so a system service');
      console.error('  (Windows Defender real-time scan or Windows Search) has the handle.');
      console.error('  Clear it with ANY of:');
      console.error('    • reboot, or');
      console.error('    • elevated PowerShell:');
      console.error('        Stop-Service WSearch -Force; Remove-Item "' + winUnpacked + '" -Recurse -Force');
      console.error('    • resmon → CPU → Associated Handles → search "app.asar" → End process');
      console.error('  Then re-run: npm run build:installer');
      console.error('');
      process.exit(1);
    }
  }
  if (!fs.existsSync(winUnpacked)) {
    console.log('[build-installer-signed] Cleared stale ' + outDir + '\\win-unpacked before build.');
  }
}
freeStaleBuildDir();

// ─── electron-builder ───────────────────────────────────────────────────────
const args = ['electron-builder', '--win', 'nsis', '--x64'];
console.log('[build-installer-signed] Running: npx', args.join(' '));

const result = spawnSync('npx', args, {
  cwd: repoRoot,
  stdio: 'inherit',
  env,
  shell: true,
});

if (result.error) {
  console.error('[build-installer-signed] Failed to spawn electron-builder:', result.error.message);
  process.exit(1);
}
if (result.status !== 0) {
  console.error('[build-installer-signed] electron-builder exited with status', result.status);
  process.exit(result.status || 1);
}

// ─── Locate the built installer ─────────────────────────────────────────────
//
// CRITICAL: when prior installers are still present in release/ (the dev
// hasn't pruned old versions), `readdirSync` returns them in NTFS-sorted
// order and `Array.find` happily returns the FIRST match — which is
// almost always the OLDER version. The post-build verification gates
// (size floor, signature pin, SHA-512 log) would then run against the
// wrong file, masking real problems with the actual freshly-built EXE.
//
// We avoid this by:
//   1. Preferring the file whose version EXACTLY matches package.json
//      (the version we just built).
//   2. Falling back to the most-recently-modified Setup .exe so the gate
//      still works for hotfix builds where someone bumped the version
//      between invocations.
function findInstaller() {
  if (!fs.existsSync(releaseDir)) return null;
  const files = fs.readdirSync(releaseDir);
  const setupFiles = files.filter((f) => /setup.*\.exe$/i.test(f));
  if (setupFiles.length === 0) return null;

  // 1. Prefer exact version match against package.json
  let pkgVersion = null;
  try { pkgVersion = require(path.join(repoRoot, 'package.json')).version; } catch (_) {}
  if (pkgVersion) {
    const exact = setupFiles.find((f) =>
      f.toLowerCase().includes('-' + pkgVersion.toLowerCase() + '.')
    );
    if (exact) return path.join(releaseDir, exact);
  }

  // 2. Fallback: newest by mtime
  const ranked = setupFiles
    .map((f) => ({ f, mtimeMs: fs.statSync(path.join(releaseDir, f)).mtimeMs }))
    .sort((a, b) => b.mtimeMs - a.mtimeMs);
  return path.join(releaseDir, ranked[0].f);
}

const installerPath = findInstaller();
if (!installerPath) {
  console.error('[build-installer-signed] FATAL: could not locate built installer in', releaseDir);
  process.exit(1);
}
console.log('');
console.log('[build-installer-signed] Installer:', installerPath);

// ─── GATE 2: Post-build signature verification ──────────────────────────────
if (signed) {
  if (!fs.existsSync(verifyScript)) {
    console.error('[build-installer-signed] FATAL: verification script missing:', verifyScript);
    process.exit(1);
  }

  const psArgs = [
    '-NoProfile',
    '-ExecutionPolicy', 'Bypass',
    '-File', verifyScript,
    '-Path', installerPath,
    '-ExpectedThumbprint', expectedThumbprint,
  ];

  console.log('[build-installer-signed] Verifying signature…');
  const verify = spawnSync('powershell.exe', psArgs, {
    cwd: repoRoot,
    stdio: ['ignore', 'pipe', 'pipe'],
  });

  const stdout = (verify.stdout || '').toString().trim();
  const stderr = (verify.stderr || '').toString().trim();
  stdout.split(/\r?\n/).filter(Boolean).forEach((line) => console.log('  ' + line));

  if (verify.status !== 0) {
    console.error('[build-installer-signed] FATAL: signature verification FAILED (exit=' + verify.status + ')');
    if (stderr) {
      stderr.split(/\r?\n/).filter(Boolean).forEach((line) => console.error('  ' + line));
    }
    console.error('  electron-builder may have silently skipped signing.');
    console.error('  Check its output above for timestamp server errors, expired cert, or missing signtool.');
    process.exit(1);
  }
}

// ─── GATE 3: Installer size floor + SHA-512 log ─────────────────────────────
const stat = fs.statSync(installerPath);
const sizeMB = (stat.size / (1024 * 1024)).toFixed(1);
console.log('');
console.log('[build-installer-signed] Installer size: ' + stat.size + ' bytes (' + sizeMB + ' MB)');

if (stat.size < MIN_INSTALLER_BYTES) {
  const floorMB = (MIN_INSTALLER_BYTES / (1024 * 1024)).toFixed(0);
  console.error(
    '[build-installer-signed] FATAL: installer is only ' + sizeMB + ' MB, below ' + floorMB + ' MB floor.',
  );
  console.error('  Post-slim healthy builds are ~180-220 MB. This build is likely missing one or more');
  console.error('  Python service EXEs (InverterCoreService.exe, ForecastCoreService.exe,');
  console.error('  CalibratorService.exe) or other bundled assets. Do NOT upload.');
  process.exit(1);
}

// Compute SHA-512 (the hash electron-updater will expect in latest.yml).
// Stream to avoid loading 620 MB into memory.
const hash = crypto.createHash('sha512');
const stream = fs.createReadStream(installerPath);
stream.on('data', (chunk) => hash.update(chunk));
stream.on('end', () => {
  const digest = hash.digest('base64');
  console.log('[build-installer-signed] SHA-512 (base64): ' + digest);
  console.log('');
  
  // Clean release directory: keep only installer, blockmap, and latest.yml
  const keepFiles = [
    path.basename(installerPath),
    path.basename(installerPath) + '.blockmap',
    'latest.yml'
  ];
  const allFiles = fs.readdirSync(releaseDir);
  let cleanedCount = 0;
  for (const f of allFiles) {
    if (!keepFiles.includes(f)) {
      try {
        fs.rmSync(path.join(releaseDir, f), { recursive: true, force: true });
        cleanedCount++;
      } catch (err) {
        console.warn('[build-installer-signed] WARNING: failed to clean up ' + f + ': ' + err.message);
      }
    }
  }
  if (cleanedCount > 0) {
    console.log('[build-installer-signed] Cleaned ' + cleanedCount + ' intermediate files from release/ directory.');
  }

  console.log('[build-installer-signed] Build OK — ready for upload');
  process.exit(0);
});
stream.on('error', (err) => {
  console.error('[build-installer-signed] Failed to compute SHA-512:', err.message);
  process.exit(1);
});
